#define F_CPU 16000000UL      // klockfrekvensen, behövs av _delay_ms
#include <avr/io.h>
#include <util/delay.h>

#define LED_PIN 5             // digital pin 13 = PB5

int main(void) {
    DDRB |= (1 << LED_PIN);   // pinnen som utgång
    while (1) {
        PORTB ^= (1 << LED_PIN);   // flippa LED:en
        _delay_ms(500);
    }
    return 0;
}
